ch.consume('orders', (msg) => {
  let order;
  try {
    order = Order.decode(msg.content);       // throws on a bad payload
  } catch (err) {
    return ch.nack(msg, false, false);       // requeue=false -> DLX
  }
  handle(order).then(() => ch.ack(msg), () => ch.nack(msg, false, true));
}, { noAck: false });
